import React from "react";
import {Button, Paper, Stack, Table, TableBody, TableCell, TableHead, TableRow, Typography} from "@mui/material";
import {Link} from "react-router-dom";
import {Receipt} from "./warehouseReceiptsApi";

export default function ReceiptDetails({receipt, children}: {receipt: Receipt; children?: React.ReactNode}) {
    return <Paper variant="outlined" sx={{p: 2}}><Stack direction="row" justifyContent="space-between" flexWrap="wrap"><Typography fontWeight={700}>Приёмка {new Date(receipt.createdAt).toLocaleString("ru-RU")}</Typography><Button component={Link} to={`/collaboration?kind=receipt&id=${receipt.id}&view=tasks`}>Поставить задачу</Button>{children}</Stack>
        {receipt.transportWaybillId && <Button component={Link} to={`/invoices/${receipt.transportWaybillId}`}>{receipt.sourceDocumentKind === 1 ? "ТН" : "ТТН"} {receipt.sourceDocumentNumber || `#${receipt.transportWaybillId}`}</Button>}
        {receipt.sourceDocumentKind != null && !receipt.transportWaybillId && <Typography color="text.secondary">Накладная {receipt.sourceDocumentNumber || ""} удалена из архива. Запись проведённого прихода сохранена.</Typography>}
        {receipt.comment && <Typography>{receipt.comment}</Typography>}<Table size="small"><TableHead><TableRow><TableCell>Товар / GTIN</TableCell><TableCell>Принято</TableCell><TableCell>Было → стало</TableCell></TableRow></TableHead><TableBody>{receipt.lines.map(line => <TableRow key={line.productId}><TableCell>{line.productName}<Typography variant="caption" display="block">{line.gtin}</Typography></TableCell><TableCell>{line.quantity}</TableCell><TableCell>{line.stockBefore} → {line.stockAfter}</TableCell></TableRow>)}</TableBody></Table></Paper>;
}
