import React from "react";
import {Alert, Button, CircularProgress, Stack} from "@mui/material";
import {Link, useParams} from "react-router-dom";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {useReceiptQuery} from "./warehouseReceiptsApi";
import ReceiptDetails from "./ReceiptDetails";

export default function InvoiceReceiptPage() {
    const {receiptId = ""} = useParams();
    const receipt = useReceiptQuery(receiptId, {skip: !receiptId});
    const isInvoice = receipt.data && (receipt.data.sourceDocumentKind != null || receipt.data.transportWaybillId != null);
    return <MainDiv><Stack spacing={2}><PageTitle>История прихода по накладной</PageTitle>
        <Button component={Link} to="/invoices?archive=Archived">Архив файлов для прихода</Button>
        {receipt.isLoading && <CircularProgress/>}
        {(receipt.isError || (receipt.data && !isInvoice)) && <Alert severity="error">Приход по файлу недоступен.</Alert>}
        {isInvoice && receipt.data && <ReceiptDetails receipt={receipt.data}/>}
    </Stack></MainDiv>;
}
